<script setup>
import { computed, inject, onBeforeUnmount, watch } from 'vue'
import { useRoute } from 'vue-router'
import { formatPublicPrice } from '@/utils/public-catalog.js'
import { loadPricingAuthSession, publicPriceState, publicPricingAuthOptions } from '@/utils/public-pricing-query.js'
import { usePublicI18n } from '@/i18n/public-runtime.js'
const route = useRoute(); const { store, ready } = inject('public-home-publication')
const { t } = usePublicI18n()
const modelKey = computed(() => String(route.params.modelKey || '')); const validModelKey = computed(() => /^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(modelKey.value)); const slot = computed(() => { if (!validModelKey.value) return { status: 'not_found', data: null }; if (store.value.site.status === 'error') return { status: 'error', data: null }; if (store.value.site.status !== 'ready') return { status: 'loading', data: null }; return store.value.details[modelKey.value] || { status: 'loading', data: null } })
const model = computed(() => slot.value.data?.model)
let disposed = false; let auth = null; let stopAuth = null; let authProbe = null
const options = () => publicPricingAuthOptions(auth)
async function load(key = modelKey.value) { await ready; if (disposed || key !== modelKey.value || !validModelKey.value) return null; await store.loadSite(options()); if (disposed || key !== modelKey.value || store.value.site.status !== 'ready') return null; if (!auth && store.value.site.data?.priceVisibility === 'authenticated_only') { authProbe ||= loadPricingAuthSession(true, () => import('@/api/request.js')); const restored = await authProbe; if (disposed || key !== modelKey.value) return null; if (restored) { auth = restored; stopAuth = auth.subscribe(() => { void load() }); await store.loadSite(options()) } } if (disposed || key !== modelKey.value) return null; return store.loadModel(key, options()) }
watch(modelKey, (key, _prior, onCleanup) => { load(key); onCleanup(() => store.cancel(`detail:${key}`)) }, { immediate: true })
onBeforeUnmount(() => { disposed = true; stopAuth?.(); store.cancel(`detail:${modelKey.value}`) })
const stableURL = computed(() => `/pricing/${encodeURIComponent(modelKey.value)}`)
const price = component => { const state = publicPriceState(model.value, component); return { ...state, label: state.state === 'published' ? formatPublicPrice(state.value).label : t(`pricingCatalog.${state.state === 'login_required' ? 'loginRequired' : 'unpublished'}`) } }
</script>
<template><article class="pricing-detail"><RouterLink to="/pricing">← {{ t('pricingCatalog.back') }}</RouterLink><section v-if="slot.status === 'loading'" class="detail-state" role="status">{{ t('pricingCatalog.loadingModel') }}</section><section v-else-if="slot.status === 'not_found'" class="detail-state" role="alert"><h1>{{ t('pricingCatalog.notFound') }}</h1><p>{{ t('pricingCatalog.notFoundHelp') }}</p></section><section v-else-if="slot.status === 'gone'" class="detail-state" role="alert"><h1>{{ t('pricingCatalog.gone') }}</h1><p>{{ t('pricingCatalog.goneHelp') }}</p></section><section v-else-if="slot.status === 'login_required'" class="detail-state" role="status">{{ t('pricingCatalog.loginRequired') }}</section><section v-else-if="slot.status === 'error'" class="detail-state" role="alert"><h1>{{ t('pricingCatalog.unavailableTitle') }}</h1><p>{{ t('pricingCatalog.unavailableHelp') }}</p><button class="public-button" type="button" @click="load">{{ t('retry') }}</button></section><template v-else-if="model"><header><p class="public-eyebrow">{{ model.provider }}</p><h1>{{ model.displayName }}</h1><code>{{ model.modelKey }}</code><span class="sr-only">{{ stableURL }}</span></header><div class="detail-prices"><section><h2>{{ t('pricingCatalog.inputPrice') }}</h2><strong>{{ price('input').label }}</strong><p v-if="price('input').state === 'published'">{{ t('pricingCatalog.inputUnit') }}</p></section><section><h2>{{ t('pricingCatalog.outputPrice') }}</h2><strong>{{ price('output').label }}</strong><p v-if="price('output').state === 'published'">{{ t('pricingCatalog.outputUnit') }}</p></section></div><p class="detail-disclaimer" role="note">{{ t('pricingCatalog.disclaimer') }}</p><dl><div><dt>{{ t('pricingCatalog.provider') }}</dt><dd>{{ model.provider }}</dd></div><div><dt>{{ t('pricingCatalog.contextWindow') }}</dt><dd>{{ model.contextWindow.toLocaleString() }} Token</dd></div><div><dt>{{ t('pricingCatalog.capabilities') }}</dt><dd><span v-for="item in model.capabilities" :key="`cap-${item}`">{{ item }}</span><span v-for="item in model.endpointTypes" :key="`endpoint-${item}`">{{ item }}</span></dd></div><div><dt>{{ t('pricingCatalog.displayGroup') }}</dt><dd>{{ model.publicDisplayGroup || '—' }}</dd></div><div v-if="model.publicRestrictions?.length"><dt>{{ t('pricingCatalog.restrictions') }}</dt><dd><span v-for="item in model.publicRestrictions" :key="item">{{ item }}</span></dd></div><div v-if="model.priceSource"><dt>{{ t('pricingCatalog.source') }}</dt><dd>{{ model.priceSource }}</dd></div><div v-if="model.priceReviewer"><dt>{{ t('pricingCatalog.reviewer') }}</dt><dd>{{ model.priceReviewer }}</dd></div><div v-if="model.effectiveAt"><dt>{{ t('pricingCatalog.effectiveAt') }}</dt><dd>{{ model.effectiveAt }}</dd></div><div><dt>{{ t('pricingCatalog.updatedAt') }}</dt><dd>{{ model.updatedAt }}</dd></div><div><dt>{{ t('pricingCatalog.snapshot') }}</dt><dd>{{ model.releaseVersion }}</dd></div></dl><RouterLink class="public-button" to="/chat">{{ t('console') }}</RouterLink></template></article></template>
<style scoped>.pricing-detail{width:min(920px,calc(100% - 48px));margin:0 auto;padding:64px 0 96px}.pricing-detail>header{margin:42px 0}.pricing-detail h1{font-size:clamp(36px,5vw,54px);margin:8px 0}.pricing-detail code{color:var(--public-muted)}.detail-prices{display:grid;grid-template-columns:1fr 1fr;gap:20px}.detail-prices section,.detail-state,.pricing-detail dl{padding:24px;border:1px solid var(--public-border);border-radius:16px;background:var(--public-card)}.detail-prices strong{font-family:ui-monospace,SFMono-Regular,monospace;font-size:32px}.detail-prices p{color:var(--public-muted)}.detail-disclaimer{margin:24px 0;padding:16px 20px;border-left:4px solid var(--public-primary);background:#eff6ff;color:#1e3a8a}.pricing-detail dl{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pricing-detail dt{color:var(--public-muted)}.pricing-detail dd{margin:6px 0 0}.pricing-detail dd span{display:inline-block;margin-right:7px}.pricing-detail :focus-visible{outline:3px solid var(--public-primary);outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:767px){.pricing-detail{width:calc(100% - 32px);padding-top:42px}.detail-prices,.pricing-detail dl{grid-template-columns:1fr}}/* 375px */@media(min-width:768px){.pricing-detail{max-width:920px}}/* 768px */@media(min-width:1440px){.pricing-detail{max-width:920px}}/* 1440px */</style>
